export type ColumnType = 'text' | 'code' | 'money' | 'percent' | 'pp' | 'date' | 'number' | 'hash' | 'status';

export interface ColumnSchema {
  key: string;
  label: string;
  type: ColumnType;
  /** Column created by this step: what the agent did. */
