}

export interface ColumnFilter {
  key: string;
  op: 'contains' | 'eq' | 'gt' | 'lt';
  value: string;
}

export interface PreviewQuery {
  dataset?: string;
  page: number;
  page_size: number;
  sort?: { key: string; dir: 'asc' | 'desc' } | null;
