}

export interface PreviewPage {
  dataset?: string;
  datasets?: string[];
  step_id: string;
  state: 'ready' | 'pending' | 'running' | 'not_tabular' | 'failed';
  schema: ColumnSchema[];
  rows: PreviewRow[];
  total_rows: number;
  page: number;
  page_size: number;
